Get-ADComputer -Filter {OperatingSystem -notlike "*server*"} -SearchBase "OU=EndPoints,DC=boticario,DC=net" -Properties Name,Created,Description,DistinguishedName,Enabled,LastLogonDate,OperatingSystem,OperatingSystemVersion| select Name,Created,Description,DistinguishedName,Enabled,LastLogonDate,OperatingSystem,OperatingSystemVersion| Export-Csv -Path c:\temp\ADComputers_boticario.csv -NoTypeInformation -Delimiter ";" -Encoding UTF8